SELECT analytics_order_facts.category, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 3 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.payment_method = 'invoice' GROUP BY analytics_order_facts.category ORDER BY contribution_margin ASC, analytics_order_facts.category ASC LIMIT 3
